const body = $input.first().json.body || {};

const tenant_id = body.tenant_id;
const user_id = body.user_id;
const game_id = body.game_id;
const analysis = body.analysis || {};

// Validation
const errors = [];
if (!tenant_id) errors.push('tenant_id requis');
if (!user_id) errors.push('user_id requis');
if (!game_id) errors.push('game_id requis');

// Analysis validation
if (Object.keys(analysis).length === 0) {
  errors.push('analysis requis (objet non vide)');
}

if (analysis.accuracy) {
  if (typeof analysis.accuracy.white !== 'number' && typeof analysis.accuracy.black !== 'number') {
    errors.push('analysis.accuracy doit contenir white et/ou black (nombres)');
  }
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' }
    }
  };
}

return {
  json: {
    valid: true,
    tenant_id,
    user_id,
    game_id,
    analysis
  }
};

const response = $input.first().json;

const statusCode = response.statusCode || 200;
const body = response.body || response;

if (statusCode === 404) {
  return {
    json: {
      success: false,
      error: {
        code: 404,
        message: 'Partie non trouvee',
        game_id: $('Validate Input').first().json.game_id
      }
    }
  };
}

if (statusCode >= 400 || body.success === false) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: body.error?.message || 'Erreur API',
        details: body
      }
    }
  };
}

return {
  json: {
    success: true,
    message: 'Analyse mise a jour',
    game_id: $('Validate Input').first().json.game_id
  }
};

